import json
import ast
import re
from collections import Counter
from typing import List, Tuple, Optional

def perceive(observation_history: list[str]) -> str:
    """
    Parse the current raw observation (last element of history) and return a concise
    text summary of decision‑relevant features. The output must be non‑empty, never
    raise exceptions, and change between consecutive states if the world moves.

    Supports two encodings:
      (A) ARC integer grid – rows as bracketed comma‑separated ints after a marker.
      (B) Autumn string grid – a single JSON 2‑D array of colour names.

    Additionally, extracts step number and action count from the metadata (common
    to both formats) so that consecutive states always differ even when the grid
    appears unchanged.
    """
    try:
        obs = observation_history[-1]
    except IndexError:
        return "empty_history"

    # ------------------- Parse metadata (step, action count) -------------------
    step = None
    actcnt = None
    step_match = re.search(r"Step:\s*(\d+)", obs)
    if step_match:
        step = int(step_match.group(1))
    actcnt_match = re.search(r"Action count:\s*(\d+)", obs)
    if actcnt_match:
        actcnt = int(actcnt_match.group(1))

    # ------------------- Parse the grid (try JSON first, then ARC int) --------
    grid = None

    # Try Autumn (JSON) format: locate outermost [[ ... ]]
    start_idx = obs.find("[[")
    end_idx = obs.rfind("]]")
    if start_idx != -1 and end_idx != -1 and end_idx > start_idx:
        try:
            parsed = json.loads(obs[start_idx:end_idx+2])
            if isinstance(parsed, list) and len(parsed) > 0 and isinstance(parsed[0], list):
                grid = parsed
        except (json.JSONDecodeError, ValueError):
            pass

    # Fallback: ARC integer grid (lines starting/ending with brackets)
    if grid is None:
        rows = []
        for line in obs.splitlines():
            line = line.strip()
            if line.startswith('[') and line.endswith(']'):
                try:
                    row = ast.literal_eval(line)
                    if isinstance(row, list) and all(isinstance(x, int) for x in row):
                        rows.append(row)
                except (ValueError, SyntaxError, MemoryError):
                    continue
        if rows and len(set(len(r) for r in rows)) == 1:   # rectangular
            grid = rows

    # ------------------- Determine background colour --------------------------
    background = None
    non_bg = []  # list of (row, col, value)

    if grid is not None:
        flat = [cell for row in grid for cell in row]
        if flat:
            background = Counter(flat).most_common(1)[0][0]

        for r, row in enumerate(grid):
            for c, val in enumerate(row):
                if val != background:
                    non_bg.append((r, c, val))

    # ------------------- Build summary string ---------------------------------
    parts = []

    # Metadata
    if step is not None:
        parts.append(f"step={step}")
    if actcnt is not None:
        parts.append(f"actcnt={actcnt}")

    # Grid status
    if grid is None:
        parts.append("grid_not_found")
    elif not non_bg:
        parts.append("all_background")
    else:
        # Format each non‑background cell
        cell_strs = []
        for r, c, val in non_bg:
            # Normalise colour to string (for both int and string cells)
            colour_str = str(val)
            cell_strs.append(f"({r},{c}):{colour_str}")
        parts.append("cells " + " ".join(cell_strs))

    summary = " ".join(parts)

    # Ensure non‑empty and within length limit
    if not summary:
        summary = "unknown_state"

    if len(summary) > 1990:
        # Truncate with an overflow count
        truncated = summary[:1980] + f"... (+{len(non_bg)-5} cells)" if non_bg else summary[:1980] + "..."
        if len(truncated) < 2000:
            return truncated
        else:
            return summary[:1995] + "..."

    return summary
